SELECT * FROM places WHERE is_active = 1 AND category != 'STATION'
AND category = #{category}
AND name LIKE CONCAT('%', #{keyword}, '%')
AND address LIKE CONCAT('%', #{district}, '%')
ORDER BY name LIMIT #{limit} OFFSET #{offset}
